            .beginner = "the arguments listed one by one in `with`",
        },
    },
    .syntax_error = &.{
        .{
            .code = "bad character",
            .raised_when = "A character outside a text literal or comment starts no token",
        },
        .{
            .code = "unterminated text",
            .raised_when = "An ordinary text literal is unclosed at its line end, or a fenced literal is unclosed at EOF; reported at its opener",
        },
        .{
            .code = "bad unit",
            .raised_when = "A Unit after a numeric literal names a factor the Unit Catalogue doesn't have, has a malformed or negative exponent, or names two Units of one Unit Kind",
        },
        .{
            .code = "unexpected token",
            .raised_when = "A token can't continue the parse, including the end of a line or of the source",
        },
        .{
            .code = "not a container",
            .raised_when = "A Container's root isn't a name, e.g. `put 1 into 3`; reported at the Container's first token",
        },
        .{
            .code = "unterminated interpolation",
            .raised_when = "A hole is unclosed at EOF; reported at its dollar-brace opener",
        },
        .{
            .code = "empty interpolation",
            .raised_when = "An interpolation hole contains no expression",
        },
        .{
            .code = "invalid text escape",
            .raised_when = "A backtick escape is malformed, octal, or produces an unpaired surrogate",
        },
        .{
            .code = "invalid text indentation",
            .raised_when = "Fenced text does not match its closing margin",
        },
        .{
            .code = "invalid text delimiter",
            .raised_when = "A raw closing quote run is longer than its opening fence",
        },
    },
    .units = .{
        .catalogue = "units.toml",
    },
};
